(* [comment removed for export] *)
Lemma stepBW pcB wr raW lo hi kb a (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  runBW pcB wr raW lo hi -> PENTBA.ntb_specA RSEGS AD L ar HI wr kb P -> lo <= u <= hi -> 0 <= kb -> L5.ra_ok raW ->
  INV Mq mdq LKq Awq crq kq a -> xhi + a + kb <= xhi + W -> inregs Rq sp (PMSPA.o_v AD fb) u -> csk Rq ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, INV M2 md2 LK2 Aw2 cr2 k2 (a + kb) -> inregs R2 sp (PMSPA.o_v AD fb) u -> csk R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 raW M2 md2) K) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq pcB Mq mdq) K.
